# ✅ [audit12] shared helper of the batch verify scripts: law <pass>/<fail> <repo-relative test file> [bun test args]  (pinned bun from ROOT, no parent envelope, SEMIO_TEST_ARTIFACT_DIR=$ART = ROOT/.cache/test-sandbox/ac-v unless LAWENV gives the whole environment delta; sets FAILED); mode: python3 -I C/xplat5-tools/tests/test_stage_mode.py on this stage.py; parse: C/gate-g-tools/scan.ts over the batch's TS files
BUN=${BUN:-$HOME/Library/Caches/semio/runtimes/bun/90987a3a16d7db556d886ac3d551e7b6d3edf0a1cf43acaed622e8676be1d12f/bun}; FAILED=0; C=$(cd "$HERE/../../.." && pwd); LOGS="$C/🗑️generated/audit12/verify"; ART="$ROOT/.cache/test-sandbox/ac-v"; mkdir -p "$LOGS" "$ART"
law(){ want="$1"; f="$2"; shift 2; log="$LOGS/$(printf '%s%s' "$f" "$*" | shasum | cut -c1-10).log"
 (cd "$ROOT" && env -u SEMIO_SCRIPT_PROCESS_INVOCATION ${LAWENV:-SEMIO_TEST_ARTIFACT_DIR=$ART} nice -n 10 "$BUN" test --timeout 170000 "./$f" "$@" > "$log" 2>&1 </dev/null)
 got="$(grep -aE '^ *[0-9]+ pass$' "$log" | tail -1 | tr -dc 0-9)/$(grep -aE '^ *[0-9]+ fail$' "$log" | tail -1 | tr -dc 0-9)"
 if [ "$got" = "$want" ]; then echo "ok   $got $f $*"; else echo "FAIL $got (want $want) $f $*  log: $log"; grep -aE '^\(fail\)' "$log" | cut -c1-200; FAILED=1; fi; }
mode(){ python3 -I "$C/xplat5-tools/tests/test_stage_mode.py" "$HERE/stage.py" >/dev/null 2>&1 && echo "ok   stage.py mode law" || { echo "FAIL stage.py mode law"; FAILED=1; }; }
parse(){ python3 -I -c 'import json,sys;[print(r) for r in json.load(open(sys.argv[1],encoding="utf8")) if r.endswith((".ts",".mts",".mjs"))]' "$HERE/manifest.json" > "$LOGS/scan.list"; [ -s "$LOGS/scan.list" ] || return 0; out=$(cd "$ROOT" && "$BUN" "$C/gate-g-tools/scan.ts" "$LOGS/scan.list" "$LOGS/scan" | tail -1); case "$out" in *"bad 0") echo "ok   parse $out";; *) echo "FAIL parse $out"; FAILED=1;; esac; }
applied(){ python3 -I "$HERE/stage.py" check --root "$ROOT" | grep -v '^applied' && { echo "batch not applied at $ROOT"; exit 2; }; true; }
